def transform(grid):
 h,w=len(grid),len(grid[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==0 or (r,c) in seen: continue
   color=grid[r][c]; pts=[]; stack=[(r,c)]; seen.add((r,c))
   while stack:
    y,x=stack.pop(); pts.append((y,x))
    for a,b in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
      seen.add((a,b)); stack.append((a,b))
   comps.append((pts,min(y for y,x in pts),max(y for y,x in pts),min(x for y,x in pts),max(x for y,x in pts)))
 frames=[]
 for obj in comps:
  p,t,b,l,r=obj
  s=set(p)
  if b-t>=2 and r-l>=2 and all((y,x) in s for y in range(t,b+1) for x in range(l,r+1) if y in (t,b) or x in (l,r)):
   frames.append(obj)
 candidates=[o for o in comps if any(o[1]>f[1] and o[2]<f[2] and o[3]>f[3] and o[4]<f[4] for f in frames)]
 if not candidates: candidates=[o for o in comps if o not in frames] or comps
 if not candidates:return [[0]]
 p,t,b,l,r=max(candidates,key=lambda o:len(o[0]))
 out=[[0]*(r-l+1) for _ in range(b-t+1)]
 for y,x in p:out[y-t][x-l]=grid[y][x]
 return out

